use super::{CallbackSlot, IosDisplay, platform::IosPlatformState};
use accesskit_ios::SubclassingAdapter;
use gpui::accesskit::{
    ActionHandler, ActionRequest, ActivationHandler, DeactivationHandler, TreeUpdate,
};

/// The accessibility handlers GPUI installs after the window is constructed.
#[derive(Default)]
struct IosA11y {
    callbacks: Option<gpui::A11yCallbacks>,
    /// UIKit requested a tree before GPUI installed its callbacks.
    activation_pending: bool,
}

/// Forwards the adapter's callbacks to the GPUI callbacks currently installed.
#[derive(Clone)]
struct IosA11yHandlers(Rc<RefCell<IosA11y>>);

impl ActivationHandler for IosA11yHandlers {
    fn request_initial_tree(&mut self) -> Option<TreeUpdate> {
        if self.0.borrow().callbacks.is_none() {
            // A later `a11y_init` activates the adapter once GPUI is ready.
            self.0.borrow_mut().activation_pending = true;
            return None;
        }
        with_a11y_callbacks(&self.0, |callbacks| (callbacks.activation)()).flatten()
    }
}

impl ActionHandler for IosA11yHandlers {
    fn do_action(&mut self, request: ActionRequest) {
        let _ = with_a11y_callbacks(&self.0, |callbacks| (callbacks.action)(request));
    }
}

impl DeactivationHandler for IosA11yHandlers {
    fn deactivate_accessibility(&mut self) {
        if with_a11y_callbacks(&self.0, |callbacks| (callbacks.deactivation)()).is_none() {
            // UIKit withdrew an activation that arrived before `a11y_init`.
            self.0.borrow_mut().activation_pending = false;
        }
    }
}

/// Runs one GPUI callback with the callbacks taken out of the cell, so a
/// handler that re-enters the platform cannot borrow the cell twice.
fn with_a11y_callbacks<R>(
    a11y: &Rc<RefCell<IosA11y>>,
    run: impl FnOnce(&mut gpui::A11yCallbacks) -> R,
) -> Option<R> {
    let mut callbacks = a11y.borrow_mut().callbacks.take()?;
    let result = run(&mut callbacks);
    let mut shared = a11y.borrow_mut();
    // Callbacks installed by a re-entrant `a11y_init` win.
    if shared.callbacks.is_none() {
        shared.callbacks = Some(callbacks);
    }
    Some(result)
}

/// Installs the AccessKit adapter on `view` before UIKit can show it.
///
/// QUARANTINE: `accesskit_ios` 0.1.2 exposes only a constructor that panics on
/// a null view, off the main thread, or for a view that already has an adapter.
/// The preconditions hold by construction: `view` is a live `Retained<MetalView>`,
/// `IosWindow::new` runs on the main thread, and it adds one adapter per window.
fn install_a11y_adapter(
    view: &Retained<MetalView>,
    a11y: &Rc<RefCell<IosA11y>>,
) -> SubclassingAdapter {
    let handlers = IosA11yHandlers(Rc::clone(a11y));
    // SAFETY: the window keeps `view` alive for as long as the adapter exists.
    unsafe {
        SubclassingAdapter::new(
            Retained::as_ptr(view).cast_mut().cast(),
            handlers.clone(),
            handlers.clone(),
            handlers,
        )
    }
}

