    fn a11y_init(&self, callbacks: gpui::A11yCallbacks) {
        let pending = {
            let mut a11y = self.a11y.borrow_mut();
            a11y.callbacks = Some(callbacks);
            std::mem::take(&mut a11y.activation_pending)
        };
        if !pending {
            return;
        }
        // UIKit activated the adapter before GPUI could serve a tree, so it
        // holds a placeholder. Activation returns GPUI's initial window tree and
        // schedules the full frame whose update replaces it.
        let initial = with_a11y_callbacks(&self.a11y, |callbacks| (callbacks.activation)());
        if let Some(initial) = initial.flatten() {
            self.a11y_tree_update(initial);
        }
    }

    fn a11y_tree_update(&self, tree_update: TreeUpdate) {
        let events = self
            .a11y_adapter
            .borrow_mut()
            .as_ref()
            .and_then(|adapter| adapter.update_if_active(|| tree_update));
        if let Some(events) = events {
            events.raise();
        }
    }
